o hasta autorización","receipt":"AIS30/v0.6/U17-C16/receipt.json","on_failure":"HOLD_NO_PUBLISH","separate_reviewer_required":false}},{"checkpoint_code":"U17-C17","title":"Rechazos, anomalías y recuperación","evidence_to_close":"Prueba REJECTED/PAUSED/ACCOUNT_RESTRICTED con causa, suspensión y rollback.","status":"NOT_VERIFIED","checkpoint_origin":"V0_6_META_PAID_ADS","operational_contract":{"contract":"AIS30-CP/v1","input":"Oferta, activos Meta, reglas de plataforma/Perú, audiencia y CRM","process":"Procesar revisión/rechazo de Meta, bloqueo de cuenta, errores API, claims rechazados y rollback, sin republicación evasiva.","output":"Prueba REJECTED/PAUSED/ACCOUNT_RESTRICTED con causa, suspensión y rollback.","verify":"prueba controlada y readback API/CRM sin gasto hasta autorización","receipt":"AIS30/v0.6/U17-C17/receipt.json","on_failure":"HOLD_NO_PUBLISH","separate_reviewer_required":false}},{"checkpoint_code":"U17-C18","title":"E2E de entrega publicitaria y oportunidad","evidence_to_close":"En dry-run readback de estado PAUSED; con pauta autorizada, evidence DELIVERY+IMPRESSIONS+spend+CRM y pausa de cierre.","status":"NOT_VERIFIED","checkpoint_origin":"V0_6_META_PAID_ADS","operational_contract":{"contract":"AIS30-CP/v1","input":"Oferta, activos Meta, reglas de plataforma/Perú, audiencia y CRM","process":"Ensayar eligibility→creative→campaign→PAUSED→aprobación; activación y gasto solo con autorización adicional por monto, verificando entrega y CRM.","output":"En dry-run readback de estado PAUSED; con pauta autorizada, evidence DELIVERY+IMPRESSIONS+spend+CRM y pausa de cierre.","verify":"prueba controlada y readback API/CRM sin gasto hasta autorización","receipt":"AIS30/v0.6/U17-C18/receipt.json","on_failure":"HOLD_NO_PUBLISH","separate_reviewer_required":false}}]}],"counts":{"units":18,"checkpoints":180,"verified_ai_sales_checkpoints":0,"original_checkpoints":102,"added_checkpoints":60,"prior_checkpoints":162,"meta_ads_checkpoints":18},"dependencies":{"pe10":"Profile Updater PE10 exists in Supabase and has active backlog; read live states before reuse. No duplicate PE10 in AI Sales."},"previous_version":{"version":"v0.5","event_id":21630,"source_ref":"docs/ai_sales/AI_SALES_3_0_PLAN_V0_5_MOTOR_COMERCIAL_20261027.json","blob_sha":"a2ac034c09dee4ee6d890bc50ec8f70b69df65e3","immutable":true},"registered_state_at_revision":{"units":17,"checkpoints":102,"pending":102,"closed":0,"base_event_id":21611},"benchmark_2026":{"schema":"AI_SALES_BENCHMARK_CHANGESET_V1","source_category":"Documented vendor practices reviewed 2026; policy and legal applicability must be confirmed before enablement","change_type":"CHECKPOINT_ACCEPTANCE_CRITERIA_ENRICHMENT_ONLY","changed_checkpoint_count":20,"changed_checkpoint_codes":["U00-C05","U02-C03","U02-C04","U04-C02","U04-C04","U05-C01","U06-C01","U07-C04","U08-C03","U08-C04","U08-C05","U09-C04","U10-C02","U10-C04","U11-C01","U11-C05","U12-C02","U12-C04","U15-C10","U16-C09"],"risk_controls":["CONTACT_PRESSURE_BUDGET","SINGLE_ACTIVE_SEQUENCE","SINGLE_OUTBOUND_OWNER","PRE_SEND_ADMISSION","DETERMINISTIC_CHANNEL_ELIGIBILITY","EVENT_DRIVEN_STOP","EXPLAINABLE_SCORING","RATE_LIMIT_AND_TRANSPORT","RELEASE_GATING"],"benchmark_examples_not_authorized_defaults":{"status":"CALIBRATION_CANDIDATES_ONLY","max_active_sequences_per_contact":1,"max_outbound_14_days":2,"max_outbound_30_days":4,"min_hours_between_outbound":72,"max_contacts_per_organization_7_days":3,"note":"Numbers are hypotheses for authorized marketing campaigns; must not be hardcoded; platform and local consent policies prevail; not applied to legitimate inbound support replies."},"precedence":"LEGAL_AND_PLATFORM_POLICIES > CONSENT_AND_OPTOUT > CONTACT_OWNER_AND_SEQUENCE > CONTACT_PRESSURE > SCORE_OR_LLM","dynamic_policy_authority":"Policy by business, product category, channel, purpose and current version; NOT Router static if-statements","research_flags":[{"key":"META_WHATSAPP_FINANCIAL","status":"BLOCK_PENDING_SPECIFIC_USE_CASE_ELIGIBILITY","alternative":"Seller-facing internal web app"},{"key":"PERU_CONSENT_ADVERTISING","status":"REQUIRE_CURRENT_OFFICIAL_LEGAL_CONFIRMATION_BEFORE_SEND"},{"key":"LINKEDIN_TERMS","status":"NO_UNAUTHORIZED_SCRAPING_OR_BULK_AUTO_MESSAGING"},{"key":"EMAIL_SENDER_POLICY","status":"REQUIRE_DOMAIN_AUTHENTICATION_AND_UNSUBSCRIBE_WHERE_APPLICABLE"}],"evaluation_scope":"One consolidated functional readback per lot by the implementing team; no external reviewer gate for any checkpoint.","no_runtime_activation":true,"no_schema_redesign":true,"no_new_units":true},"review_policy":{"applies_to":"ALL_102_CHECKPOINTS","model":"SELF_VALIDATION_BY_IMPLEMENTING_TEAM","additional_reviewer_required":false,"verification":"Focused functional checks, relevant regression, exact-source and Supabase readback","applies_to_profiles_and_agents":true,"no_extra_checkpoints_added":true,"existing_security_and_merge_train_controls_unchanged":true},"change_summary":{"change_kind":"DELETE_OPTIONAL_REVIEW_GATE","checkpoints_updated":["U16-C09"],"rules_updated":2,"benchmark_scope_updated":1,"unit_policy_keys_removed":["legacy_separate_reviewer_flag"],"checkpoint_ids_changed":0,"checkpoint_status_changed":0,"affected_units":17,"work_item_criteria_updated":17},"market_engine_v05":{"flow":["ICP","DISCOVERY_MULTISOURCE","RESOLVE_RUC_AND_DOMAIN","VERIFY_NEWS_CLAIMS","ENRICH_ACCOUNT","BUYER_GRAPH","CONTACT_WATERFALL","LEGAL_ELIGIBILITY","SCORING","OUTBOX_ADMISSION","QUEUE_DISPATCH","REPLY_CLASSIFY","CRM_MEETING","B2B_ONBOARD","SOURCE_ROI_FEEDBACK"],"sources":[["SUNAT","identidad, RUC y actividad"],["sitios oficiales","sede, sector, canales institucionales"],["SEACE","contratos públicos"],["empleo","posibles señales de contratación"],["gremios y cámaras","empresas por sector"],["redes sociales permitidas","señal y roles"],["noticias y reguladores","eventos verificables"],["formularios y referidos propios","intención declarada"]],"algorithms":{"entity_resolution":"RUC exacto > dominio corporativo confirmado > nombre y evidencia adicional; homónimos/filiales ambiguos en HOLD","source_truth":"Afirmación, fecha, RUC/empresa, fuente primaria, corroboración no sindicada, contradicción, TTL; VERIFIED/CORROBORATED/UNVERIFIED/CONTRADICTED/STALE","contact_cascade":"canal corporativo oficial > contacto aportado voluntariamente > fuente autorizada > NO_VERIFICADO; score por rol×origen×vigencia; email inferido no verificado","qualification":"Fit,Intent,Recency,Engagement con score explicable y abstención; score nunca otorga SEND_ALLOWED","admission":"producto/categoría/canal/finalidad/consentimiento/baja/owner/presión/horario/actividad/lease; fail closed","outbox":"DRAFT→APPROVED→SCHEDULED→CLAIMED→SENT y PAUSED/RETRY/FAILED/CANCELLED; lease e idempotencia","learning":"fuente→cuenta→decisor→contactable permitido→respuesta→reunión→propuesta→convenio; costo y falsos positivos por etapa"},"market_proof":{"sample":"30–50 empresas como hipótesis de muestra ajustable","mode":"manual/semiautomatizado, sin despachos masivos por defecto","kpis":["cuentas verificadas","señales sustentadas","decisor válido","contactabilidad legal","respuesta/reunión cuando permitido","costo por cuenta útil"],"decision":"GO/REWORK/STOP con evidencia, sin umbrales inventados"},"source_access":"Comprobar licencias/ToS de cada fuente al ejecutar, sin extracción prohibida","runtime_activation":false},"normalization_v05":{"baseline":102,"added":60,"total":162,"units":17,"gates":5,"allocation":{"U00":{"original":5,"added":3,"total":8},"U01":{"original":10,"added":3,"total":13},"U02":{"original":5,"added":6,"total":11},"U03":{"original":5,"added":4,"total":9},"U04":{"original":5,"added":4,"total":9},"U05":{"original":5,"added":1,"total":6},"U06":{"original":5,"added":4,"total":9},"U07":{"original":5,"added":12,"total":17},"U08":{"original":5,"added":8,"total":13},"U09":{"original":5,"added":3,"total":8},"U10":{"original":5,"added":2,"total":7},"U11":{"original":5,"added":2,"total":7},"U12":{"original":5,"added":4,"total":9},"U13":{"original":5,"added":0,"total":5},"U14":{"original":5,"added":2,"total":7},"U15":{"original":12,"added":1,"total":13},"U16":{"original":10,"added":1,"total":11}},"all_checkpoints_pending":true,"no_additional_reviewer":true,"no_runtime_activation":true},"meta_paid_ads_v06":{"unit":"U17","scope":"META_PAID_ADS_FB_IG_NOT_WHATSAPP","status":"PLANNED_NO_ADS_PUBLISHED","checkpoint_count":18,"eligibility":{"default":"DENY_UNTIL_VERIFIED","salary_advance_promotions":"PROHIBITED_UNLESS_CLEAR_CURRENT_META_ELIGIBILITY_FOR_EXACT_OFFER","corporate_b2b_branding":"NOT_AUTO_EXEMPT_CHECK_ACTUAL_OFFER_AND_LANDING","special_category":"VERIFY_PER_MARKET_DO_NOT_COPY_US_ONLY_RULES_TO_PERU","required":"offer+creative+CTA+landing+target_country"},"workflow":["POLICY_CHECK","ACCOUNT_VERIFY","CAMPAIGN_OBJECTIVE","TARGETING","CREATIVE","CREATE_PAUSED","HUMAN_SPEND_APPROVAL","META_REVIEW","DELIVERY","INSIGHTS","CRM_QUALITY","OPTIMIZE_OR_STOP"],"api":["Marketing API","Insights API","Lead Ads","Pixel/Conversions API only where permitted"],"budget":"No media spend unless explicit additional approval with cap and dates; no API license purchase by this plan","measurement":["impressions","reach","spend","frequency","cpm","ctr","cpl","crm_mql","crm_sql","qualified_meeting","signed_employer","cost_per_signed_employer"],"data_principle":"No financial sensitive data; CAPI/Pixels only allowed events, consent/purpose and data-source restrictions","compliance_stop":["banned_offer","unapproved_spend","rejected_meta_review","ad_account_restricted","data_sharing_violation","fatigue_or_quality_stop"],"cross_unit_checkpoint_codes":["U00-C05","U02-C08","U02-C10","U04-C02","U08-C06","U09-C06","U11-C06","U12-C04","U16-C11"],"no_independent_review":true,"no_runtime_activation":true},"normalization_v06":{"prev_units":17,"new_units":1,"total_units":18,"prev_checkpoints":162,"new_checkpoints":18,"total_checkpoints":180,"enriched_existing_checkpoints":9,"old_ids_and_progress_preserved":true,"no_independent_reviewer":true,"no_runtime_activation":true}}$ais30_snapshot_v06$::jsonb;
 v_exec text; v_old_event bigint; v_old_digest text; v_event bigint;
 v_unit jsonb; v_cp jsonb; v_code text; v_new_unit jsonb; v_new_work bigint;
 v_workstream bigint; v_new_plan_unit bigint; v_inputs jsonb; v_digest text;
 v_i integer := 0; v_j integer; v_seen integer := 0; v_added integer := 0;
 v_units_updated integer := 0; v_cross_changed integer := 0;
BEGIN
 SELECT execution_id INTO v_exec
 FROM public.lf_operation_execution
 WHERE operation_code='ACTUALIZACION_DB_LF'
 AND target_type='MIGRATION'
 AND target_code LIKE '%lf_ai_sales_3_0_meta_paid_ads_plan_v0_6'
 AND status='IN_PROGRESS' ORDER BY created_at DESC LIMIT 1;
 IF v_exec IS NULL THEN RAISE EXCEPTION 'AIS30_META_V06_GOVERNED_TRAIN_REQUIRED'; END IF;

 IF p->>'plan_code'<>'AI_SALES_3_0'
    OR p->>'snapshot_version'<>'v0.6'
    OR p->>'status'<>'DRAFT_REVISION_PROPOSED'
    OR p#>>'{previous_version,version}'<>'v0.5'
    OR (p#>>'{previous_version,event_id}')::bigint<>21630
    OR jsonb_array_length(p->'units')<>18
    OR jsonb_array_length(p->'gates')<>5
    OR (p->'counts'->>'units')::int<>18
    OR (p->'counts'->>'checkpoints')::int<>180
    OR (p->'counts'->>'meta_ads_checkpoints')::int<>18
    OR (p->'counts'->>'verified_ai_sales_checkpoints')::int<>0
    OR p#>>'{normalization_v06,no_runtime_activation}'<>'true'
    OR p#>>'{meta_paid_ads_v06,status}'<>'PLANNED_NO_ADS_PUBLISHED'
 THEN RAISE EXCEPTION 'AIS30_META_V06_SNAPSHOT_INVALID'; END IF;

 SELECT id,payload->>'snapshot_digest' INTO v_old_event,v_old_digest
 FROM public.lf_eventos WHERE evento_tipo='PLAN_SNAPSHOT_DETALLADO'
 AND entidad_tipo='ENGINEERING_PLAN' AND entidad_codigo='AI_SALES_3_0'
 AND payload->>'version'='v0.5' ORDER BY id DESC LIMIT 1;
 IF v_old_event IS DISTINCT FROM 21630
 OR v_old_digest IS DISTINCT FROM 'f0ac59f0d9cffe2504096a81d77da041509bdf910a763180a6195dc0e9f7193d'
 OR (SELECT count(*) FROM public.lf_eventos WHERE entidad_tipo='ENGINEERING_PLAN'
      AND entidad_codigo='AI_SALES_3_0' AND evento_tipo='PLAN_SNAPSHOT_DETALLADO')<>4
 OR (SELECT count(*) FROM programacion.engineering_plan_units WHERE plan_code='AI_SALES_3_0')<>17
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
      JOIN programacion.engineering_plan_units u ON u.work_item_id=c.work_item_id
      WHERE u.plan_code='AI_SALES_3_0' AND c.status='PENDING')<>162
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
      JOIN programacion.engineering_plan_units u ON u.work_item_id=c.work_item_id
      WHERE u.plan_code='AI_SALES_3_0')<>162
 OR EXISTS(SELECT 1 FROM programacion.engineering_plan_units u
      WHERE u.plan_code='AI_SALES_3_0' AND (
      NOT (u.unit_metadata ? 'revision_v0_5')
      OR u.unit_metadata ? 'revision_v0_6'
      OR u.unit_metadata ? 'independent_review_only_if_material_risk'))
 OR EXISTS(SELECT 1 FROM programacion.engineering_work_items WHERE work_code='AIS30-U17')
 OR EXISTS(SELECT 1 FROM programacion.engineering_plan_units WHERE plan_code='AI_SALES_3_0' AND unit_code='U17')
 OR EXISTS(SELECT 1 FROM public.lf_eventos WHERE entidad_tipo='ENGINEERING_PLAN'
      AND entidad_codigo='AI_SALES_3_0' AND payload->>'version'='v0.6')
 THEN RAISE EXCEPTION 'AIS30_META_V06_PRESTATE_OR_DUPLICATE'; END IF;

 SELECT id INTO v_workstream FROM programacion.engineering_workstreams
 WHERE stream_code='WS-AI-SALES-3-0' AND status='PLANNED';
 IF v_workstream IS NULL THEN RAISE EXCEPTION 'AIS30_META_V06_WORKSTREAM_MISSING'; END IF;

 v_digest:=encode(extensions.digest(convert_to(p::text,'UTF8'),'sha256'),'hex');
 INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,
   payload,origen,created_by_execution_id)
 VALUES('PLAN_SNAPSHOT_DETALLADO','ENGINEERING_PLAN','AI_SALES_3_0',
 'AI Sales 3.0 v0.6: Meta Ads publicidad pagada, sin presupuesto ni anuncios activados; 18 unidades/180 checkpoints.',
 'INFO',jsonb_build_object(
 'evidence_schema_version','operational-event/v2','producer','LF_MIGRATION_MERGE_TRAIN',
 'purpose','Record planned Meta Ads campaign delivery and optimization with strict financial-offer and human-spend publication gates.',
 'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
 'execution_id',v_exec,'acceptance_declared',false,
 'plan_code','AI_SALES_3_0','version','v0.6','previous_version','v0.5',
 'previous_snapshot_event_id',v_old_event,'status','DRAFT_REVISED_NOT_EXECUTED',
 'unit_count',18,'checkpoint_count',180,'new_checkpoint_count',18,
 'snapshot_digest',v_digest,'source_ref','github://cristhianlujan/claude-persona-lf-patch/docs/ai_sales/AI_SALES_3_0_PLAN_V0_6_META_ADS_20261027.json',
 'no_runtime_activation',true,'media_spend_authorized',false,'ads_published',false,
 'snapshot',p),'GOVERNED_MIGRATION_SOURCE_FIRST',v_exec)
 RETURNING id INTO v_event;

 FOR v_unit IN SELECT value FROM jsonb_array_elements(p->'units') x(value)
 LOOP
   v_i:=v_i+1;
   v_code:=v_unit->>'unit_code';
   IF v_code IS DISTINCT FROM ('U'||lpad((v_i-1)::text,2,'0'))
   THEN RAISE EXCEPTION 'AIS30_META_V06_UNIT_ORDER_INVALID:%',v_code; END IF;
   IF v_code='U17' THEN
      v_new_unit:=v_unit;
      EXIT;
   END IF;
   IF (SELECT count(*) FROM programacion.engineering_work_checkpoints c
       JOIN programacion.engineering_plan_units u ON u.work_item_id=c.work_item_id
       WHERE u.plan_code='AI_SALES_3_0' AND u.unit_code=v_code AND c.status='PENDING')
       <>jsonb_array_length(v_unit->'checkpoints')
   THEN RAISE EXCEPTION 'AIS30_META_V06_CHECKPOINT_COUNT_DRIFT:%',v_code; END IF;

   v_j:=0;
   FOR v_cp IN SELECT value FROM jsonb_array_elements(v_unit->'checkpoints') x(value)
   LOOP
     v_j:=v_j+1;v_seen:=v_seen+1;
     IF v_cp->>'checkpoint_code' IS DISTINCT FROM v_code||'-C'||lpad(v_j::text,2,'0')
       OR v_cp->>'status'<>'NOT_VERIFIED'
       OR v_cp#>>'{operational_contract,separate_reviewer_required}'<>'false'
       OR NOT EXISTS(SELECT 1 FROM programacion.engineering_plan_units u
          JOIN programacion.engineering_work_checkpoints c ON c.work_item_id=u.work_item_id
          WHERE u.plan_code='AI_SALES_3_0' AND u.unit_code=v_code
          AND c.checkpoint_code=v_cp->>'checkpoint_code'
          AND c.title=v_cp->>'title' AND c.sequence_no=v_j AND c.status='PENDING')
     THEN RAISE EXCEPTION 'AIS30_META_V06_PRIOR_CP_DRIFT:%',v_cp->>'checkpoint_code'; END IF;
     IF v_cp ? 'cross_unit_meta_ads_v06' THEN
       UPDATE programacion.engineering_plan_units u
       SET unit_metadata=jsonb_set(
          jsonb_set(u.unit_metadata,ARRAY['checkpoint_inputs',v_cp->>'checkpoint_code','evidence_to_close'],to_jsonb(v_cp->>'evidence_to_close'),false),
          ARRAY['checkpoint_inputs',v_cp->>'checkpoint_code','operational_contract','output'],to_jsonb(v_cp->>'evidence_to_close'),false)
       WHERE u.plan_code='AI_SALES_3_0' AND u.unit_code=v_code
         AND u.unit_metadata->'checkpoint_inputs' ? (v_cp->>'checkpoint_code');
       IF NOT FOUND THEN RAISE EXCEPTION 'AIS30_META_V06_CROSS_UNIT_CP_MISSING:%',v_cp->>'checkpoint_code'; END IF;
       v_cross_changed:=v_cross_changed+1;
     END IF;
   END LOOP;
   UPDATE programacion.engineering_plan_units u SET
      unit_metadata=u.unit_metadata || jsonb_build_object('revision_v0_6',
         jsonb_build_object('event_id',v_event,'snapshot_digest',v_digest,'version','v0.6',
         'new_meta_ads_unit','U17','no_runtime_activation',true,
         'separate_reviewer_required',false,'applied_by_execution_id',v_exec))
   WHERE u.plan_code='AI_SALES_3_0' AND u.unit_code=v_code
   AND u.unit_metadata ? 'revision_v0_5' AND NOT(u.unit_metadata ? 'revision_v0_6');
   IF NOT FOUND THEN RAISE EXCEPTION 'AIS30_META_V06_PRIOR_UNIT_CHANGED:%',v_code; END IF;
   v_units_updated:=v_units_updated+1;
 END LOOP;

 IF v_i<>18 OR v_seen<>162 OR v_cross_changed<>9 OR v_units_updated<>17
 OR v_new_unit->>'unit_code'<>'U17' OR jsonb_array_length(v_new_unit->'checkpoints')<>18
 OR v_new_unit->>'phase'<>'F2' OR v_new_unit->>'runtime_activation'<>'false'
 THEN RAISE EXCEPTION 'AIS30_META_V06_NEW_UNIT_OR_CROSS_LINKS_INVALID'; END IF;

 INSERT INTO programacion.engineering_work_items(
   work_code,workstream_id,title,objective,expected_result,work_type,priority,status,
   assignee_type,assignee_ref,target_repo,target_domain,target_component,
   source_ref,acceptance_criteria,created_by_execution_id)
 VALUES('AIS30-U17',v_workstream,'U17 — Meta Ads: campañas, publicación y optimización',
   'Definir y probar publicidad Meta de ofertas B2B genuinamente elegibles, solo con aprobación de pauta.',
   'Plan de campañas, creatividad, API, landing, lead CRM, medición, presupuesto y elegibilidad con evidencia.',
   'AGENT_PLATFORM','P2','BACKLOG','MIXED','AI_SALES_PLAN_OWNER',
   'cristhianlujan/claude-persona-lf-patch','AI_SALES','U17',
   'event://' || v_event,
   jsonb_build_array('No external checkpoint reviewer',
   'No access tokens, campaign activation or media spend from plan registration',
   'Meta financial product eligibility is verified per exact offer, creative, CTA, landing and country',
   'Ad publishing requires separate human approval specifying currency, limit, period and account',
   'Lead generation and Pixel/CAPI respect privacy, sensitive-data rules and platform restrictions',
   'Tests and exact readback before any checkpoint DONE'),
   v_exec)
 RETURNING id INTO v_new_work;

 FOR v_cp IN SELECT value FROM jsonb_array_elements(v_new_unit->'checkpoints') x(value)
 LOOP
   v_added:=v_added+1;v_code:=v_cp->>'checkpoint_code';
   IF v_code IS DISTINCT FROM ('U17-C'||lpad(v_added::text,2,'0'))
   OR v_cp->>'status'<>'NOT_VERIFIED'
   OR v_cp#>>'{operational_contract,contract}'<>'AIS30-CP/v1'
   OR v_cp#>>'{operational_contract,separate_reviewer_required}'<>'false'
   OR length(coalesce(v_cp->>'evidence_to_close',''))<10
   THEN RAISE EXCEPTION 'AIS30_META_V06_NEW_CP_INVALID:%',v_code; END IF;
   INSERT INTO programacion.engineering_work_checkpoints(
      work_item_id,checkpoint_code,title,sequence_no,weight,required,status,created_by_execution_id)
   VALUES(v_new_work,v_code,v_cp->>'title',v_added,1,true,'PENDING',v_exec);
 END LOOP;
 IF v_added<>18 THEN RAISE EXCEPTION 'AIS30_META_V06_NEW_CP_COUNT_INVALID'; END IF;

 SELECT jsonb_object_agg(cp.value->>'checkpoint_code',
    jsonb_build_object('title',cp.value->>'title',
      'evidence_to_close',cp.value->>'evidence_to_close',
      'status','PENDING',
      'operational_contract',cp.value->'operational_contract','origin','V0_6_META_PAID_ADS'))
 INTO v_inputs FROM jsonb_array_elements(v_new_unit->'checkpoints') AS cp(value);

 -- The plan_units table intentionally has no generated ID; allocate safely under an exclusive DML mutex.
 LOCK TABLE programacion.engineering_plan_units IN SHARE ROW EXCLUSIVE MODE;
 SELECT coalesce(max(id),0)+1 INTO v_new_plan_unit FROM programacion.engineering_plan_units;
 INSERT INTO programacion.engineering_plan_units(
 id,plan_code,unit_code,unit_class,lot_code,lot_from,lot_to,title,exit_criterion,
 plan_event_id,work_item_id,created_by_execution_id,unit_metadata)
 VALUES(v_new_plan_unit,'AI_SALES_3_0','U17','EXECUTION','F2',18,18,
 'U17 — Meta Ads: campañas, publicación y optimización',
 'Sólo anuncios elegibles, validación de creatividad, permisos Meta y aprobación separada de gasto.',
 v_event,v_new_work,v_exec,jsonb_build_object(
 'schema','AI_SALES_META_PAID_PLAN_V0_6','phase','F2',
 'checkpoint_inputs',v_inputs,'operating_protocol_v0_6',v_new_unit->'operating_protocol',
 'no_runtime_activation',true,'separate_reviewer_required',false,
 'revision_v0_6',jsonb_build_object('event_id',v_event,'snapshot_digest',v_digest,'version','v0.6',
 'new_meta_ads_unit','U17','created_by_execution_id',v_exec,'media_spend_authorized',false,
 'ad_creation_authorized',false,'no_runtime_activation',true)));

 IF (SELECT count(*) FROM programacion.engineering_plan_units WHERE plan_code='AI_SALES_3_0')<>18
 OR (SELECT count(*) FROM programacion.engineering_plan_units WHERE plan_code='AI_SALES_3_0'
    AND unit_metadata ? 'revision_v0_6')<>18
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
     JOIN programacion.engineering_plan_units u ON c.work_item_id=u.work_item_id
     WHERE u.plan_code='AI_SALES_3_0')<>180
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
     JOIN programacion.engineering_plan_units u ON c.work_item_id=u.work_item_id
     WHERE u.plan_code='AI_SALES_3_0' AND c.status='PENDING')<>180
 OR (SELECT count(*) FROM programacion.engineering_work_checkpoints c
     JOIN programacion.engineering_plan_units u ON c.work_item_id=u.work_item_id
     WHERE u.plan_code='AI_SALES_3_0' AND c.created_by_execution_id=v_exec)<>18
 OR (SELECT count(*) FROM public.lf_eventos
     WHERE evento_tipo='PLAN_SNAPSHOT_DETALLADO' AND entidad_tipo='ENGINEERING_PLAN'
     AND entidad_codigo='AI_SALES_3_0')<>5
 OR EXISTS(SELECT 1 FROM programacion.engineering_plan_units u
     WHERE u.plan_code='AI_SALES_3_0' AND u.unit_metadata ? 'independent_review_only_if_material_risk')
 THEN RAISE EXCEPTION 'AIS30_META_V06_POSTSTATE_INTEGRITY_FAILED'; END IF;
END;
$ais30_meta_ads$;
COMMIT;
